import {
  DatePicker,
  DatePickerCalendar,
  DatePickerContent,
  DatePickerInput,
} from "@/registry/erbium/ui/date-picker";

const Example = (args: {
  mode: "single" | "range";
  disabled: boolean;
  closeOnSelect: boolean;
  numberOfMonths: number;
  captionLayout: "label" | "dropdown";
}) => (
  <DatePicker
    // Remount when the mode changes so each mode starts from an empty value.
    key={args.mode}
    mode={args.mode}
    disabled={args.disabled}
    closeOnSelect={args.closeOnSelect}
  >
    <DatePickerInput aria-label="Date" className="w-72" />
    <DatePickerContent>
      <DatePickerCalendar numberOfMonths={args.numberOfMonths} captionLayout={args.captionLayout} />
    </DatePickerContent>
  </DatePicker>
);

export default Example;
